 function resetCountdown(resetAt,now=Date.now()){const ms=Number(resetAt)-now;if(!Number.isFinite(ms)||!resetAt)return '';if(ms<=0)return L.t('resetSoon');const days=Math.floor(ms/86400000),hours=Math.floor(ms%86400000/3600000),minutes=Math.ceil(ms%3600000/60000);if(days)return L.t('daysHoursLeft',{d:days,h:hours});if(hours)return L.t('hoursLeft',{h:hours,m:minutes});return L.t('minutesLeft',{n:Math.max(1,minutes)});}
