 function segmentPercent(s,id){const estimate=root.GlanceAdvice?.sessionEquivalent?.(s),current=(s?.windows||[])[0],observed=Math.max(id==='claude'?8:4,Math.min(25,100-(Number(current?.remaining)||90)));return estimate?.segmentPercent||observed;}
