   const rawDetail=String(e.detail||''),expiry=entitlement&&e.expiresAt&&!/(?:期限|expires?|expiration)/i.test(rawDetail)?L.t('expiresAt',{date:date(e.expiresAt)}):'',detail=[rawDetail?extraDetail(rawDetail):'',expiry].filter(Boolean).join(' · '),warning=urgent?'<span class="expiry-warning" aria-hidden="true">⚠︎ </span>':'';
