 function historyRows(s,labelValue){const aliases=labelValue==='週間 (Work / Codex)'?['週間 (Work / Codex)','Work / Codex · 週間']:labelValue==='Work / Codex · 週間'?['Work / Codex · 週間','週間 (Work / Codex)']:[labelValue];return aliases.flatMap(key=>s?.history?.[key]||[]).sort((a,b)=>a.capturedAt-b.capturedAt).filter((r,i,rows)=>i===0||r.remaining!==rows[i-1]?.remaining).slice(-HISTORY_LIMIT);}
 function historyBox(s){const labels=[...(s?.windows||[]).map(w=>w.label),...Object.keys(s?.history||{})].filter((name,index,all)=>all.indexOf(name)===index),groups=labels.map(name=>{const rows=historyRows(s,name).reverse(),shown=label(name),lines=rows.map(r=>`${historyDate(r.capturedAt)}  ${L.t('remainingUsage',{value:value(r.remaining)})}`).join('\n');return `<section class="history-group"><div class="history-label">${escape(shown)} <span>${escape(L.t('items',{n:rows.length.toLocaleString(L.locale())}))}</span></div>${rows.length?`<textarea class="history-log" readonly wrap="off" aria-label="${escape(shown+' '+L.t('history'))}">${escape(lines)}</textarea>`:`<div class="history-empty">${escape(L.t('recordOnChange'))}</div>`}</section>`}).join('');return `<div class="history"><div class="extras-title">${escape(L.t('history'))}</div>${groups||`<div class="history-empty">${escape(L.t('historyEmpty'))}</div>`}</div>`;}
